Drupal.behaviors.tooltip={attach(e){let t=e.querySelectorAll(`.js-tooltip`);function n(e,t){document.addEventListener(`click`,n=>{e.contains(n.target)||t.classList.remove(`tooltip__content--visible`)})}function r(e,t){let r=e.querySelector(`.js-tooltip__content`);r.classList.contains(`tooltip__content--visible`)?(t.setAttribute(`aria-expanded`,`false`),r.classList.remove(`tooltip__content--visible`)):(t.setAttribute(`aria-expanded`,`true`),r.classList.add(`tooltip__content--visible`)),n(e,r)}t.forEach(e=>{let t=e.querySelector(`.tooltip__icon`);t.addEventListener(`click`,()=>{r(e,t)}),t.addEventListener(`keyup`,n=>{n.key===`Escape`&&r(e,t)})})}};